import { Locale, localeToTopLevelDomain } from '@game-studio/utilities';
import axios, { AxiosError } from 'axios';
import { ILog } from '../../../types';
import { BaseLogstashProvider } from '../base';
import { BaseLogVerbosity } from '../types';
import { PoweredByTombolaVerbosity } from './types';

enum StatusCode {
    BAD_RESPONSE = 400
}
interface ILoggingApiErrorResponse {
    type: string;
    title: string;
    status: number;
    detail: string;
    instance: string;
}

interface IFailedLog {
    EventName: string,
    Message: string
}

function isFailedLogValid(failedLog: IFailedLog) {
    return !(failedLog.EventName === 'Log' &&
        failedLog.Message === 'InvalidLog');
}

export class PoweredByTombolaLogstashProvider extends BaseLogstashProvider<PoweredByTombolaVerbosity> {

    protected handleOnSendError(logsToSend: ILog<void, PoweredByTombolaVerbosity>[], error: AxiosError<unknown, any> | Error): void {
        if (!axios.isAxiosError(error) || !error.response) {
            //error is not related to the response
            this.logs.push(...logsToSend);
            return;
        }
        const apiResponse = error.response.data as ILoggingApiErrorResponse;
        //bad response
        const isBadResponse = apiResponse.status === StatusCode.BAD_RESPONSE;
        const hadNoValidLogs = apiResponse.detail.toLowerCase().includes('no valid logs');
        if (isBadResponse && hadNoValidLogs) {
            logsToSend = this.fixInvalidLogs(logsToSend);
        }
        this.logs.push(...logsToSend);
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    protected fixInvalidLogs(failedLogs: any[]): ILog<void, PoweredByTombolaVerbosity>[] {
        return failedLogs
            .filter((log) => isFailedLogValid(log))
            .map((failedLog) => {
                return this.constructLog({
                    EventName: 'Log',
                    Message: 'InvalidLog',
                    Verbosity: 'Warning',
                    Data: failedLog
                });
            }) as ILog<void, PoweredByTombolaVerbosity>[];
    }

    protected get topLevelDomain() {
        return localeToTopLevelDomain(this.locale as Locale);
    }

    protected get storageKey(): string {
        return 'poweredbytombola.logs';
    }

    protected get TombolaDocType(): string {
        return 'game-studio.';
    }

    protected get endpoint(): string {
        if (this.options.environment === 'live') {
            return `https://log.poweredbytombola.${this.topLevelDomain}/log`;
        }
        switch (this.options.environment) {
            case 'stage':
                return `https://log.integration.poweredbytombola.${this.topLevelDomain}/log`;
            default:
                return `https://log.dev.poweredbytombola.${this.topLevelDomain}/log`;
        }
    }

    protected mapVerbosity(verbosity: BaseLogVerbosity): PoweredByTombolaVerbosity {
        switch (verbosity) {
            case 'error':
                return 'Error';
            case 'info':
                return 'Information';
            case 'warn':
                return 'Warning';
            default:
                return 'Debug';
        }
    }
}
